mapper.select:
select d.id as dept_id, d.name as dept_name, d.leader as leader, count(distinct u.id) as headcount, round(avg(p.score), 1) as avg_score, coalesce(sum(p.tasks), 0) as total_tasks, coalesce(sum(p.done), 0) as done_tasks from sys_dept d left join sys_user u on u.dept_id = d.id and u.status = 1 left join perf_record p on p.user_id = u.id
d.id = #{deptId}
group by d.id, d.name, d.leader, d.sort order by d.sort, d.id

select p.period as period, round(avg(p.score), 1) as avg_score, count(distinct p.user_id) as headcount from perf_record p join sys_user u on u.id = p.user_id
and u.dept_id = #{deptId}
group by p.period order by p.period

select d.name as label, count(u.id) as cnt from sys_dept d left join sys_user u on u.dept_id = d.id and u.status = 1
d.id = #{deptId}
group by d.id, d.name, d.sort order by d.sort

select case when u.status = 1 then '在职' else '离职' end as label, count(*) as cnt from sys_user u
u.dept_id = #{deptId}
group by u.status order by u.status desc
